
export interface CATask {
  id: string;
  tierId: string;
  monster: string;
  /** Official in-game achievement name (e.g. "Feeling Flameproof"). */
  name?: string;
  description: string;
}

// RuneScape 3 Combat Achievements — the achievements required by each
// "Combat Mastery - <Tier>" achievement on the RuneScape Wiki
// (https://runescape.wiki/w/Combat_Mastery_-_Easy … _-_Grandmaster). Each
// achievement's CombatScore equals its tier (Easy 1 … Grandmaster 6).
// `monster` uses the data/items.ts BOSSES_LIST name where the fight is a
// listed boss (e.g. Seiryu → Temple of Aminishi, Araxxi → Araxxor).
// IDs are `ca_<slug of the achievement name>` (RS3 achievements have no
// numeric task id) so `npm run ca:sync` stays idempotent.
